// === Tab: mySketch ===
function setup()
{
	createCanvas(windowWidth, windowHeight,WEBGL);
	background(100);
	colorMode(HSB,360,100,100)

	for(i=0;i<200;i++)
	{
			eval("thing"+i+"=creatething();")
	}
}

let a=0

function draw()
{
	push()
	rotateX(1.58)
	for(i=0;i<200;i++)
	{
			 eval("updatething(thing"+i+");")
	}
	a=a+.01
	pop()
}

function creatething()
{
     let thing={}
     thing.x = random(0,width/2)
     thing.y = random(-500,height/2)
		 thing.c = random(360)
		 return thing
}

function updatething(thing)
{
	rotateY(a)
	push()
	stroke(thing.c,100,95)
	fill(thing.c,100,95,10)
	thing.x=thing.x+random(-2,2)
	strokeWeight(random(9))

	circle(thing.x,thing.y,20)
	pop()
}

